'use strict';
const css=document.createElement('style');css.textContent=`.fx-hero{background:linear-gradient(120deg,#2b0b15,#131b29);border-top:3px solid #e10600}.fx-eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:2px;color:#ff7f75}.fx-title{font-size:clamp(25px,5vw,39px);font-weight:850;line-height:1.15;margin:9px 0}.fx-stats{display:flex;flex-wrap:wrap;gap:22px;margin-top:20px}.fx-stats strong{font-size:26px;display:block}.fx-stats small{color:#aeb8c8}.fx-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px}.fx-pick{width:100%;text-align:left;padding:13px;border:1px solid #344052;border-radius:10px;background:#121924;color:inherit;display:flex;align-items:center;gap:10px;min-height:78px}.fx-pick[aria-pressed=true]{border-color:#ff453b;background:#34171c;box-shadow:inset 3px 0 #ff453b}.fx-pick small{display:block;color:#aeb8c8;margin-top:4px}.fx-pick strong{font-size:15px}.fx-price{margin-left:auto;white-space:nowrap;font-weight:750}.fx-slots{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.fx-slot{padding:8px 11px;background:#202c3d;border-radius:8px;font-size:13px}.fx-toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:12px 0}.fx-toolbar label{display:flex;flex-direction:column;gap:5px;flex:1;min-width:120px;font-size:12px;color:#aeb8c8}.fx-toolbar select,.fx-toolbar input{width:100%;box-sizing:border-box}.fx-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:15px}.fx-primary{background:#e10600!important;color:#fff!important;font-weight:700}.fx-message{min-height:24px;margin-top:10px}.fx-scroll{overflow-x:auto}.fx-scroll table{min-width:460px}.fx-video{aspect-ratio:16/9;background:#070b11;border:1px solid #293348;border-radius:12px;overflow:hidden;margin:16px 0;position:relative}.fx-video iframe{width:100%;height:100%;border:0;display:block}.fx-video img{width:100%;height:100%;object-fit:cover;opacity:.7}.fx-play{position:absolute;inset:0;display:flex;align-items:center;justify-content:center}.fx-play button{font-size:17px;padding:14px 24px;background:#e10600;color:#fff;box-shadow:0 8px 25px #0008}.fx-empty{padding:30px 18px;text-align:center;border:1px dashed #344052;border-radius:12px;margin-top:16px}.fx-links{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.fx-links button{font-size:12px}.fx-cover{font-size:12px;color:#aeb8c8;line-height:1.7}.fx-note{font-size:13px;line-height:1.65;color:#aeb8c8}.fx-delta-up{color:#53dbac}.fx-delta-down{color:#ff8c85}#main>.fx-wide{grid-column:1/-1}@media(max-width:500px){.fx-grid{grid-template-columns:1fr}.fx-stats{gap:16px}.fx-stats strong{font-size:23px}.fx-toolbar{gap:10px}.fx-toolbar label{min-width:calc(50% - 10px)}.fx-pick{min-height:70px}.fx-title{font-size:28px}}`;document.head.appendChild(css);
const box=(title,body,hero=false)=>`<section class="card wide fx-wide${hero?' fx-hero':''}">${title?`<h2>${title}</h2>`:''}${body}</section>`;
const storeKey='f1hub:fantasy:v1';
let F=null,draft=null,state=null;
function baked(){const s=SNAP['current.json'].MRData.RaceTable;const map={};Object.keys(SNAP).filter(k=>k.startsWith('current/results.json?')).forEach(k=>SNAP[k].MRData.RaceTable.Races.forEach(r=>{if(!map[r.round])map[r.round]={...r,Results:[]};r.Results.forEach(x=>{if(!map[r.round].Results.some(z=>z.Driver.driverId===x.Driver.driverId))map[r.round].Results.push(x)})}));return{season:s.season,schedule:s.Races,races:Object.values(map).filter(r=>r.Results.length>=18).sort((a,b)=>+a.round-+b.round)}}
function deadline(r){const p=r.FirstPractice||r.SprintQualifying||r.Qualifying;return Date.parse(p?p.date+'T'+(p.time||'00:00:00Z'):r.date+'T'+(r.time||'00:00:00Z'))}
function driverPoints(x){const p=+x.position,finish=[25,18,15,12,10,8,6,4,2,1][p-1]||0,classified=/^(Finished|\+\d+ Laps?)$/.test(x.status||''),gain=+x.grid>0?Math.max(-10,Math.min(10,+x.grid-p)):0;return (classified?finish:0)+gain+(x.FastestLap?.rank==='1'?5:0)+(classified?0:-10)}
function teamPoints(r,ds,cs){return r.Results.reduce((s,x)=>s+(ds.includes(x.Driver.driverId)?driverPoints(x):0)+(cs.includes(x.Constructor.constructorId)?driverPoints(x):0),0)}
function loadState(){try{const x=JSON.parse(localStorage.getItem(storeKey));if(x&&x.season===F.season&&Array.isArray(x.drivers)&&Array.isArray(x.teams)&&x.drivers.length===3&&x.teams.length===2&&Array.isArray(x.history)&&Number.isFinite(x.budget)&&Number.isFinite(x.savedAt))return x}catch(e){}return {season:F.season,drivers:[],teams:[],budget:100,history:[],savedAt:0,startRound:0}}
function persist(){try{localStorage.setItem(storeKey,JSON.stringify(state));return true}catch(e){return false}}
function settle(){if(!state.savedAt)return;let changed=false;F.races.forEach(r=>{const sr=F.schedule.find(s=>s.round===r.round)||r;if(+r.round>=state.startRound&&deadline(sr)>state.savedAt&&!state.history.some(h=>h.round===r.round)){const pts=teamPoints(r,state.drivers,state.teams),delta=Math.round(Math.max(-3,Math.min(3,(pts-80)/20))*10)/10,before=state.budget;state.budget=Math.max(70,Math.round((before+delta)*10)/10);state.history.push({round:r.round,race:r.raceName,points:pts,delta:Math.round((state.budget-before)*10)/10,budget:state.budget,drivers:[...state.drivers],teams:[...state.teams]});changed=true}});if(changed)persist()}
function makeMarket(){const recent=F.races.slice(-5),last=F.races.at(-1),stand=SNAP['current/driverStandings.json'].MRData.StandingsTable.StandingsLists[0].DriverStandings;const rank=Object.fromEntries(stand.map(x=>[x.Driver.driverId,+x.position]));const active=last?last.Results:stand.map(x=>({Driver:x.Driver,Constructor:x.Constructors[0]}));F.drivers=active.map(x=>{const id=x.Driver.driverId,rr=recent.map(r=>r.Results.find(z=>z.Driver.driverId===id)).filter(Boolean),form=rr.length?rr.reduce((s,z)=>s+(+z.points||0),0)/rr.length:0;return{id,name:nm(x.Driver),driver:x.Driver,team:x.Constructor.constructorId,price:Math.round((6+25*Math.pow(Math.min(1,form/25),.7))*10)/10,form}}).sort((a,b)=>(rank[a.id]||99)-(rank[b.id]||99));const cc=SNAP['current/constructorStandings.json'].MRData.StandingsTable.StandingsLists[0].ConstructorStandings;F.teams=cc.map(x=>{const id=x.Constructor.constructorId,form=recent.length?recent.reduce((s,r)=>s+r.Results.filter(z=>z.Constructor.constructorId===id).reduce((a,z)=>a+(+z.points||0),0),0)/recent.length:0;return{id,name:x.Constructor.name,price:Math.round((10+30*Math.pow(Math.min(1,form/50),.7))*10)/10,form}})}
function cost(){return Math.round((F.drivers.filter(x=>draft.drivers.includes(x.id)).reduce((a,x)=>a+x.price,0)+F.teams.filter(x=>draft.teams.includes(x.id)).reduce((a,x)=>a+x.price,0))*10)/10}
function nextRace(){return F.schedule.find(r=>!F.races.some(z=>z.round===r.round))}
function locked(){const n=nextRace();return n&&deadline(n)<=Date.now()}
function nameOf(id,kind){return F[kind].find(x=>x.id===id)?.name||id.replaceAll('_',' ')}
function savedSlots(){return `<div class="fx-slots">${[...state.drivers.map(id=>`<span class="fx-slot">${esc(nameOf(id,'drivers'))}</span>`),...state.teams.map(id=>`<span class="fx-slot">${esc(nameOf(id,'teams'))}</span>`)].join('')||'<span class="mute">No team saved yet.</span>'}</div>`}
function historyView(){if(!state.history.length)return '<p class="mute">Your points start at the next eligible race after saving. No points or budget rewards are given for past races.</p>';return `<div class="fx-scroll">${tbl(['Race','Points','Budget change','Budget'],[...state.history].reverse().map(h=>`<tr><td>${esc(h.race)}</td><td class="n">${h.points}</td><td class="n ${h.delta>=0?'fx-delta-up':'fx-delta-down'}">${h.delta>=0?'+':''}$${h.delta.toFixed(1)}M</td><td class="n">$${h.budget.toFixed(1)}M</td></tr>`))}</div>`}
function option(x,kind){const selected=draft[kind].includes(x.id);return `<button type="button" class="fx-pick" data-kind="${kind}" data-id="${esc(x.id)}" aria-pressed="${selected}">${kind==='drivers'?av(x.driver,42,1):tl(x.id,x.name)}<span><strong>${esc(x.name)}</strong><small>${kind==='drivers'?esc(F.teams.find(t=>t.id===x.team)?.name||x.team)+' · ':''}${x.form.toFixed(1)} race pts / recent GP</small></span><span class="fx-price">$${x.price.toFixed(1)}M ${selected?'✓':'+'}</span></button>`}
function fantasyPage(){const n=nextRace(),total=state.history.reduce((s,h)=>s+h.points,0),last=state.history.at(-1);return box('',`<div class="fx-eyebrow">${F.season} · Your own pit wall</div><div class="fx-title">FANTASY GARAGE</div><div class="fx-note">3 drivers. 2 constructors. Make your picks, then let the racing do the talking.</div><div class="fx-stats"><div><strong>$${state.budget.toFixed(1)}M</strong><small>Your budget</small></div><div><strong>${total}</strong><small>Season points</small></div><div><strong>${last?last.points:'--'}</strong><small>Last scored race</small></div></div>`,true)+box('Your saved team',savedSlots()+`<div class="fx-note">${n?(locked()?`Team locked for ${esc(n.raceName)}. Editing reopens once its race result is baked into the site.`:`Next: ${esc(n.raceName)}. Team locks ${new Date(deadline(n)).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})} IST (first scheduled session).`):'Season complete. Your history stays on this device.'} Saves are local to this browser, not a shared league.</div>`)+box('Build your team',`<div class="fx-toolbar"><label>Find a driver or team<input id="fx-search" type="search" placeholder="Name or team" autocomplete="off"></label><label>Order<select id="fx-sort"><option value="form">Championship / form</option><option value="cheap">Price: low to high</option><option value="expensive">Price: high to low</option></select></label></div><div id="fx-budget"></div><h3>Drivers <span id="fx-dcount"></span></h3><div class="fx-grid" id="fx-drivers"></div><h3 style="margin-top:22px">Constructors <span id="fx-tcount"></span></h3><div class="fx-grid" id="fx-teams"></div><div class="fx-actions"><button id="fx-save" class="fx-primary" type="button">Save team</button><button id="fx-clear" type="button">Clear draft</button><button id="fx-revert" type="button">Back to saved team</button></div><div class="fx-message" id="fx-message" role="status" aria-live="polite"></div>`)+box('Race ledger',historyView())+box('How the game works',`<details><summary>Scoring, prices and budget rules</summary><div class="fx-note"><p>This is an unofficial, simplified F1 HUB game. It does not use official F1 Fantasy prices or rules. Only Grand Prix races count, not practice, qualifying or sprints.</p><p>Each driver: race finish points 25-18-15-12-10-8-6-4-2-1 for P1-P10; +1 per place gained / -1 per place lost from a numbered starting grid (capped at ±10); +5 for fastest lap; -10 for a non-finish or disqualification, with no finish points. Pit-lane starts (grid 0) get no position-change points. A constructor scores the sum of both its drivers. Picking a driver and their constructor counts both contributions.</p><p>After each eligible race, budget change = (team score - 80) / 20 million, rounded to $0.1M, capped at +$3M or -$3M per race. A score of 80 is neutral. Your budget never falls below <b>$70M</b>. No real money is involved.</p><p>Prices use the last five baked race results, using actual championship race points: driver price = 6 + 25 × (average points / 25)^0.7; constructor = 10 + 30 × (average points / 50)^0.7, in millions, rounded to $0.1M and capped at $31M / $40M. Prices refresh after new results are baked. Existing picks are retained if their price rises above your budget, but a new save must fit the budget.</p><p>Your last saved lineup rolls into future races automatically. Saving or editing is locked from the first scheduled session until the race is baked. No retroactive rewards: a result only counts if its weekend began after your saved lineup. Updating your lineup does not erase points or budget history. This browser must reopen the tab to apply newly baked results. Local storage can be cleared or edited; this is a personal game, not a competitive verified league.</p><p>Data snapshot: ${esc(SNAP_AT)}. Prices and scores follow the site's baked Jolpica results, so updates can lag the finish. No live fantasy leaderboard.</p></div></details>`)}
function showMarket(){const query=($('fx-search')?.value||'').trim().toLowerCase(),sort=$('fx-sort')?.value||'form';for(const kind of ['drivers','teams']){let list=F[kind].filter(x=>(x.name+' '+(F.teams.find(t=>t.id===x.team)?.name||'')).toLowerCase().includes(query));if(sort!=='form')list=[...list].sort((a,b)=>sort==='cheap'?a.price-b.price:b.price-a.price);$('fx-'+kind).innerHTML=list.map(x=>option(x,kind)).join('')||'<div class="mute">No matches.</div>'}const used=cost(),ok=used<=state.budget;$('fx-budget').innerHTML=`<div class="fx-stats"><div><strong class="${ok?'':'fx-delta-down'}">$${used.toFixed(1)}M</strong><small>Draft cost</small></div><div><strong class="${ok?'fx-delta-up':'fx-delta-down'}">$${(state.budget-used).toFixed(1)}M</strong><small>${ok?'Remaining':'Over budget'}</small></div></div>`;$('fx-dcount').textContent=`(${draft.drivers.length}/3)`;$('fx-tcount').textContent=`(${draft.teams.length}/2)`;$('fx-save').disabled=locked()||!nextRace()||draft.drivers.length!==3||draft.teams.length!==2||!ok;}
views.fantasy=async()=>{F=baked();makeMarket();state=loadState();settle();draft={drivers:[...state.drivers],teams:[...state.teams]};return fantasyPage()};
after.fantasy=()=>{showMarket();const message=t=>$('fx-message').textContent=t;$('fx-search').oninput=showMarket;$('fx-sort').onchange=showMarket;for(const kind of ['drivers','teams'])$('fx-'+kind).onclick=e=>{const b=e.target.closest('[data-id]');if(!b)return;if(locked()){message('The current weekend is locked. Picks reopen when its race result is available.');return}const id=b.dataset.id,a=draft[kind],i=a.indexOf(id);if(i>=0)a.splice(i,1);else if(a.length<(kind==='drivers'?3:2))a.push(id);else{message(`Remove a ${kind==='drivers'?'driver':'constructor'} before picking another.`);return}message('Draft changed. Save when your team is ready.');showMarket()};$('fx-clear').onclick=()=>{draft={drivers:[],teams:[]};showMarket();message('Draft cleared. Your saved team and history are unchanged.')};$('fx-revert').onclick=()=>{draft={drivers:[...state.drivers],teams:[...state.teams]};showMarket();message('Restored your saved picks.')};$('fx-save').onclick=()=>{if(locked()||draft.drivers.length!==3||draft.teams.length!==2||cost()>state.budget)return;const n=nextRace();if(!n)return;const prev={...state};state={...state,drivers:[...draft.drivers],teams:[...draft.teams],savedAt:Date.now(),startRound:+n.round};if(!persist()){state=prev;message('This browser could not save. Allow local storage and try again.');return}route(true).then(()=>{if($('fx-message'))$('fx-message').textContent=`Team saved for ${n.raceName}.`})};};
